{
  "intent": "CAPTURE",
  "purchase_units": [
    {
      "reference_id": "default",
      "custom_id": "ml-postman",
      "description": "Kinesis mWave Mechanical Keyboard - newegg.com",
      "amount": {
        "currency_code": "USD",
        "value": "106.95",
        "breakdown": {
          "item_total": {
            "currency_code": "USD",
            "value": "106.95"
          }
        }
      },
      "items": [
        {
          "name": "Kinesis mWave Mechanical Keyboard",
          "quantity": "1",
          "unit_amount": {
            "currency_code": "USD",
            "value": "106.95"
          },
          "category": "DIGITAL_GOODS"
        }
      ]
    }
  ],
  "payment_source": {
    "paypal": {
      "experience_context": {
        "return_url": "{{app_url}}/pay/done?status=approved",
        "cancel_url": "{{app_url}}/pay/done?status=cancelled",
        "user_action": "PAY_NOW",
        "shipping_preference": "NO_SHIPPING",
        "brand_name": "Money Lego (sandbox)"
      }
    }
  }
}

{
  "sender_batch_header": {
    "sender_batch_id": "{{sender_batch_id}}",
    "email_subject": "You have a payout",
    "email_message": "Your share from Money Lego"
  },
  "items": [
    {
      "recipient_type": "EMAIL",
      "amount": {
        "value": "2.00",
        "currency": "USD"
      },
      "receiver": "{{payout_receiver}}",
      "note": "Payout for Creator",
      "sender_item_id": "{{sender_batch_id}}-1"
    }
  ]
}

{
  "detail": {
    "currency_code": "USD",
    "reference": "ml-postman",
    "note": "Thanks for working with us.",
    "payment_term": {
      "due_date": "{{due_date}}"
    }
  },
  "primary_recipients": [
    {
      "billing_info": {
        "email_address": "{{invoice_recipient}}",
        "name": {
          "given_name": "Studio North"
        }
      }
    }
  ],
  "items": [
    {
      "name": "Website retainer",
      "quantity": "1",
      "unit_amount": {
        "currency_code": "USD",
        "value": "250.00"
      }
    }
  ]
}

{
  "subject": "Your invoice from Studio North",
  "note": "Due in 14 days.",
  "send_to_invoicer": false,
  "send_to_recipient": true
}

{
  "subject": "Friendly reminder",
  "note": "A quick nudge about this invoice.",
  "send_to_invoicer": false,
  "send_to_recipient": true
}

{
  "query": "A quiet mechanical keyboard for a small design studio",
  "limit": 6,
  "filters": {
    "availability": [
      "InStock"
    ],
    "conditions": [
      "new"
    ],
    "price": {
      "max_price": 150
    }
  }
}

{
  "event": "client.request",
  "request": "A quiet mechanical keyboard for a small design studio",
  "maxPrice": "150",
  "client": "Studio North"
}

{
  "requestKey": "{{$guid}}",
  "payload": {
    "request": "A quiet mechanical keyboard for a small design studio",
    "maxPrice": "150",
    "client": "Studio North"
  }
}

{
  "prompt": "When a client pays my $100 PayPal checkout, split the net 70/30, ask me to approve, pay out and post in Slack.",
  "requestKey": "{{$guid}}"
}
